  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 170440);
  assert.equal(totals.discount, 8522);
  assert.equal(totals.vat, 30937);
  assert.equal(totals.total, 192855);
});

test('invoiceTotals with varying quantities', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'PRINT-A3', qty: 50 },
    ],
  });
  const totals = invoiceTotals(r.value);
  assert.equal(totals.subtotal, 16150);
  assert.equal(totals.discount, 404);
  assert.equal(totals.vat, 1446);
  assert.equal(totals.total, 17192);
});

test('invoiceTotals returns discount field', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5, discountPercent: 10 }],
