test('invoiceTotals subtracts voucher from total', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const r2 = applyVoucher(invoice, { code: 'WELCOME20', amount: 2000 });
  const vouched = r2.value;
  const totals = invoiceTotals(vouched);
  const totalsWithout = invoiceTotals(invoice);
  assert.equal(totals.voucher, 2000);
  assert.equal(totals.total, totalsWithout.total - 2000);
});

test('invoiceTotals clamps total to zero when voucher exceeds amount', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  const invoice = r1.value;
  const totalsWithout = invoiceTotals(invoice);
  const r2 = applyVoucher(invoice, { code: 'BIGDISCOUNT', amount: totalsWithout.total + 5000 });
  const vouched = r2.value;
  const totals = invoiceTotals(vouched);
  assert.equal(totals.total, 0);
});

test('discountAmount with qty 9 has no bulk discount', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 9,
    unitPrice: 9500,
    vatRate: 21,
  };
  // lineTotal = 9 * 9500 = 85500, no explicit discount, no bulk discount
  assert.equal(discountAmount(line), 0);
});

test('discountAmount with qty 10 applies bulk discount', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 10,
    unitPrice: 9500,
    vatRate: 21,
  };
  // lineTotal = 10 * 9500 = 95000, no explicit discount
  // bulk discount = 95000 * 2.5% = 2375
  assert.equal(discountAmount(line), 2375);
});

test('discountAmount with qty 11 applies bulk discount', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 11,
    unitPrice: 9500,
    vatRate: 21,
  };
  // lineTotal = 11 * 9500 = 104500
  // bulk discount = 104500 * 2.5% = 2612.5 -> 2613 (rounded)
  assert.equal(discountAmount(line), 2613);
});

test('discountAmount applies bulk discount after line discount', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 10,
    unitPrice: 9500,
    vatRate: 21,
    discountPercent: 10,
  };
  // lineTotal = 95000, line discount 10% = 9500
  // after first discount = 85500, bulk discount 2.5% = 2137.5 -> 2138
  // total discount = 9500 + 2138 = 11638
  assert.equal(discountAmount(line), 11638);
});

test('discountAmount with tier discount and bulk discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const line = r.value.lines[0];
  // C-001 is gold tier, 5% discount = 4750
  // after first discount = 95000 - 4750 = 90250
  // bulk discount 2.5% = 2256 (rounded from 2256.25)
  // total = 4750 + 2256 = 7006
  assert.equal(discountAmount(line), 7006);
});

test('lineVAT with bulk discount applies to remaining amount', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 10,
    unitPrice: 9500,
    vatRate: 21,
  };
  // lineTotal = 95000, bulk discount = 2375
  // after discount = 92625, VAT 21% = 19451 (rounded from 19451.25)
  assert.equal(lineVAT(line), 19451);
});

test('invoiceTotals with bulk discount on single line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const totals = invoiceTotals(r.value);
  // lineTotal = 95000, tier discount 5% = 4750
  // after first discount = 90250, bulk discount 2.5% = 2256
  // total discount = 7006, after all discounts = 87994
  // VAT 21% = 18479 (rounded from 18478.74)
  // total = 95000 - 7006 + 18479 = 106473
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 7006);
  assert.equal(totals.vat, 18479);
  assert.equal(totals.total, 106473);
});

test('invoiceTotals with bulk discount on multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 5 },
    ],
  });
  const totals = invoiceTotals(r.value);
  // DEV-HOUR: 95000, tier 5% = 4750, after = 90250, bulk 2.5% = 2256, total discount = 7006
  // LOGO-PACK: 120000, tier 5% = 6000, after = 114000, no bulk (qty < 10), discount = 6000
  // subtotal = 215000, discount = 13006, after discount = 201994
  // VAT: DEV-HOUR on 87994 = 18479, LOGO-PACK on 114000 = 23940
  // total VAT = 42419, total = 215000 - 13006 + 42419 = 244413
  assert.equal(totals.subtotal, 215000);
  assert.equal(totals.discount, 13006);
  assert.equal(totals.vat, 42419);
  assert.equal(totals.total, 244413);
});

test('invoiceTotals with one line bulk, one without', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  const totals = invoiceTotals(r.value);
  // DEV-HOUR: gets bulk discount
  // LOGO-PACK: no bulk discount (qty = 1)
  // DEV-HOUR: 95000, tier 5% = 4750, after = 90250, bulk 2.5% = 2256, total = 7006
  // LOGO-PACK: 120000, tier 5% = 6000, no bulk, total = 6000
  // subtotal = 215000, discount = 13006
  assert.equal(totals.subtotal, 215000);
  assert.equal(totals.discount, 13006);
});

test('invoiceTotals with explicit discount and bulk discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 20 }],
  });
  const totals = invoiceTotals(r.value);
  // lineTotal = 95000, explicit discount 20% = 19000
  // after first discount = 76000, bulk discount 2.5% = 1900
  // total discount = 20900
  assert.equal(totals.discount, 20900);
});

test('discountAmount with 0% explicit discount and bulk discount', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 10,
    unitPrice: 9500,
    vatRate: 21,
    discountPercent: 0,
  };
