});

test('discountAmount with large qty applies bulk discount', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 100,
    unitPrice: 9500,
    vatRate: 21,
  };
  // lineTotal = 950000, no explicit discount
