  // after discount = 3607, VAT 9% = 324 (rounded from 324.63)
  // total = 3700 - 93 + 324 = 3931
  assert.equal(totals.discount, 93);
  assert.equal(totals.total, 3931);
});

test('bulk discount exactly at threshold qty 10', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 10,
    unitPrice: 100,
    vatRate: 21,
  };
  // lineTotal = 1000, bulk discount 2.5% = 25
  assert.equal(discountAmount(line), 25);
});

test('bulk discount just below threshold qty 9', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 9,
    unitPrice: 100,
    vatRate: 21,
  };
  // lineTotal = 900, no bulk discount
  assert.equal(discountAmount(line), 0);
});

