import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, discountAmount, lineVAT, applyVoucher } from '../src/invoices.js';
import { normalizeId } from '../src/customers.js';
import { renderInvoiceText } from '../src/render.js';
import { recordPayment } from '../src/payments.js';

test('createInvoice succeeds with valid input', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.customerId, 'C-001');
  assert.equal(r.value.issueDate, '2025-10-07');
  assert.equal(r.value.status, 'draft');
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(r.value.lines[0].name, 'Development (hour)');
  assert.equal(r.value.lines[0].qty, 10);
  assert.equal(r.value.lines[0].unitPrice, 9500);
  assert.equal(r.value.lines[0].vatRate, 21);
  assert.equal(r.value.lines[1].sku, 'LOGO-PACK');
  assert.equal(r.value.lines[1].name, 'Logo package');
  assert.equal(r.value.lines[1].qty, 1);
  assert.equal(r.value.lines[1].unitPrice, 120000);
  assert.equal(r.value.lines[1].vatRate, 21);
});

test('createInvoice reports unknown customer', () => {
  const r = createInvoice({
    customerId: 'C-999',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice rejects invalid date format', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '07-10-2025',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice rejects invalid date like 2025-02-30', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-30',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'DATE_INVALID' });
});

test('createInvoice rejects empty lines array', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [],
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice rejects undefined lines', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: undefined,
  });
  assert.deepEqual(r, { ok: false, error: 'NO_LINES' });
});

test('createInvoice rejects qty that is not an integer', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1.5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects qty of 0', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 0 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects negative qty', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: -5 }],
  });
  assert.deepEqual(r, { ok: false, error: 'QTY_INVALID' });
});

test('createInvoice rejects unknown SKU', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
  });
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate input', () => {
  const lines = [{ sku: 'DEV-HOUR', qty: 10 }];
  const originalLines = JSON.stringify(lines);
  createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines,
  });
  assert.equal(JSON.stringify(lines), originalLines);
});

test('createInvoice with varying VAT rates', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines[0].vatRate, 9);
  assert.equal(r.value.lines[1].vatRate, 0);
});

test('addLine adds a new line to the invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const r2 = addLine(r1.value, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 2);
  assert.equal(r2.value.lines[1].sku, 'LOGO-PACK');
  assert.equal(r2.value.lines[1].qty, 1);
  assert.equal(r2.value.lines[1].name, 'Logo package');
});

test('addLine increases qty if SKU already exists', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const r2 = addLine(r1.value, { sku: 'DEV-HOUR', qty: 5 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].qty, 15);
});

test('addLine validates qty', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const r2 = addLine(r1.value, { sku: 'LOGO-PACK', qty: 0 });
  assert.deepEqual(r2, { ok: false, error: 'QTY_INVALID' });
});

test('addLine validates SKU', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const r2 = addLine(r1.value, { sku: 'UNKNOWN-SKU', qty: 1 });
  assert.deepEqual(r2, { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine refuses to modify non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'sent',
    lines: [{ sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 9500, vatRate: 21 }],
  };
  const r = addLine(invoice, { sku: 'LOGO-PACK', qty: 1 });
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('addLine does not mutate original invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const original = JSON.stringify(r1.value);
  addLine(r1.value, { sku: 'LOGO-PACK', qty: 1 });
  assert.equal(JSON.stringify(r1.value), original);
});

test('removeLine removes the line with given SKU', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  const r2 = removeLine(r1.value, 'DEV-HOUR');
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines.length, 1);
  assert.equal(r2.value.lines[0].sku, 'LOGO-PACK');
});

test('removeLine reports LINE_NOT_FOUND for unknown SKU', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const r2 = removeLine(r1.value, 'UNKNOWN-SKU');
  assert.deepEqual(r2, { ok: false, error: 'LINE_NOT_FOUND' });
});

test('removeLine reports NO_LINES if removing the last line', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const r2 = removeLine(r1.value, 'DEV-HOUR');
  assert.deepEqual(r2, { ok: false, error: 'NO_LINES' });
});

test('removeLine refuses to modify non-draft invoices', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'sent',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 9500, vatRate: 21 },
      { sku: 'LOGO-PACK', name: 'Logo package', qty: 1, unitPrice: 120000, vatRate: 21 },
    ],
  };
  const r = removeLine(invoice, 'DEV-HOUR');
  assert.deepEqual(r, { ok: false, error: 'NOT_DRAFT' });
});

test('removeLine does not mutate original invoice', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  const original = JSON.stringify(r1.value);
  removeLine(r1.value, 'DEV-HOUR');
  assert.equal(JSON.stringify(r1.value), original);
});

test('issueInvoice sets number and status to issued', () => {
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const r2 = issueInvoice(r1.value, []);
  assert.equal(r2.ok, true);
  assert.equal(r2.value.number, 'INV-2025-0001');
  assert.equal(r2.value.status, 'issued');
