// Tier discounts (5%)
const devDiscount = round(devTotal * 0.05);
const iconDiscount = round(iconTotal * 0.05);
const logoDiscount = round(logoTotal * 0.05);
const totalDiscount = devDiscount + iconDiscount + logoDiscount;
console.log('discount:', totalDiscount);

// VAT (21%)
const devVAT = round((devTotal - devDiscount) * 0.21);
const iconVAT = round((iconTotal - iconDiscount) * 0.21);
const logoVAT = round((logoTotal - logoDiscount) * 0.21);
const totalVAT = devVAT + iconVAT + logoVAT;
console.log('vat:', totalVAT);

const total = subtotal - totalDiscount + totalVAT;
console.log('total:', total);
"

