// qty 5 DEV-HOUR 10% explicit discount, qty 1 LOGO-PACK 20% explicit discount
const devTotal = 5 * 9500;  // 47500
const logoTotal = 1 * 120000;  // 120000
const subtotal = devTotal + logoTotal;

// Explicit discounts
const devDiscount = round(devTotal * 0.10);
const logoDiscount = round(logoTotal * 0.20);
const totalDiscount = devDiscount + logoDiscount;

// VAT (21%)
const devVAT = round((devTotal - devDiscount) * 0.21);
const logoVAT = round((logoTotal - logoDiscount) * 0.21);
const totalVAT = devVAT + logoVAT;

const total = subtotal - totalDiscount + totalVAT;
console.log('Test 1 (multiple lines discounts):', { subtotal, discount: totalDiscount, vat: totalVAT, total });

// invoiceTotals with mix of discounted and non-discounted lines
// qty 5 DEV-HOUR 10% explicit, qty 1 LOGO-PACK no discount (tier 5%)
const dev2Total = 5 * 9500;  // 47500
const logo2Total = 1 * 120000;  // 120000
const sub2 = dev2Total + logo2Total;

const dev2Discount = round(dev2Total * 0.10);
const logo2Discount = round(logo2Total * 0.05);
const total2Discount = dev2Discount + logo2Discount;

const dev2VAT = round((dev2Total - dev2Discount) * 0.21);
const logo2VAT = round((logo2Total - logo2Discount) * 0.21);
const total2VAT = dev2VAT + logo2VAT;

const total2 = sub2 - total2Discount + total2VAT;
console.log('Test 2 (mix discounts):', { subtotal: sub2, discount: total2Discount, vat: total2VAT, total: total2 });

// invoiceTotals with multiple lines and different VAT rates
// qty 5 DEV-HOUR, qty 50 PRINT-A4
const dev3Total = 5 * 9500;  // 47500
const a43Total = 50 * 37;  // 1850
const sub3 = dev3Total + a43Total;

// No discounts
const dev3VAT = round(dev3Total * 0.21);
const a43VAT = round(a43Total * 0.09);
const total3VAT = dev3VAT + a43VAT;

const total3 = sub3 + total3VAT;
console.log('Test 3 (different VAT rates):', { subtotal: sub3, discount: 0, vat: total3VAT, total: total3 });
"

