node -e "
function round(v) { return Math.round(v); }

// invoiceTotals with mixed lines, discounts, and VAT
// qty 5 DEV-HOUR no explicit (tier 5%), qty 1 LOGO-PACK 15% explicit, qty 1 WORKSHOP-DAY no explicit (tier 5%)
const dev = 5 * 9500;  // 47500
const logo = 1 * 120000;  // 120000
const workshop = 1 * 60000;  // 60000
const sub = dev + logo + workshop;

const devDisc = round(dev * 0.05);
const logoDisc = round(logo * 0.15);
const workshopDisc = round(workshop * 0.05);
const disc = devDisc + logoDisc + workshopDisc;

const devVAT = round((dev - devDisc) * 0.21);
const logoVAT = round((logo - logoDisc) * 0.21);
const workshopVAT = round((workshop - workshopDisc) * 0);  // 0% VAT
const vat = devVAT + logoVAT + workshopVAT;

const total = sub - disc + vat;
console.log('mixed lines:', { subtotal: sub, discount: disc, vat, total });

// invoiceTotals with bulk discount on multiple lines
// qty 10 DEV-HOUR (tier 5%, bulk 2.5%), qty 5 LOGO-PACK (tier 5%)
const dev10 = 10 * 9500;  // 95000
const logo5 = 5 * 120000;  // 600000
const sub10 = dev10 + logo5;

const devTierDisc = round(dev10 * 0.05);  // 4750
const devAfterTier = dev10 - devTierDisc;  // 90250
const devBulkDisc = round(devAfterTier * 0.025);  // 2256
const devTotalDisc = devTierDisc + devBulkDisc;

const logoTierDisc = round(logo5 * 0.05);  // 30000
const logoTotalDisc = logoTierDisc;

const disc10 = devTotalDisc + logoTotalDisc;

const devVAT10 = round((dev10 - devTotalDisc) * 0.21);
const logoVAT5 = round((logo5 - logoTotalDisc) * 0.21);
const vat10 = devVAT10 + logoVAT5;

const total10 = sub10 - disc10 + vat10;
console.log('bulk discount multiple:', { subtotal: sub10, discount: disc10, vat: vat10, total: total10 });

// bulk discount with print line (9% VAT)
// qty 100 PRINT-A4 (bulk 2.5%)
const print = 100 * 37;  // 3700
const printBulk = round(print * 0.025);  // 93
const printVAT = round((print - printBulk) * 0.09);  // 325
const printTotal = print - printBulk + printVAT;
console.log('bulk print:', { discount: printBulk, vat: printVAT, total: printTotal });
"

