import test from 'node:test';
import assert from 'node:assert/strict';
import { lineTotal, discountAmount, lineVAT, invoiceTotals } from '../src/totals.js';
import { createInvoice, applyVoucher } from '../src/invoices.js';

test('lineTotal multiplies qty by unitPrice', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 10,
    unitPrice: 9500,
    vatRate: 21,
  };
  assert.equal(lineTotal(line), 95000);
});

test('lineTotal with qty of 1', () => {
  const line = {
    sku: 'LOGO-PACK',
    name: 'Logo package',
    qty: 1,
    unitPrice: 120000,
    vatRate: 21,
  };
  assert.equal(lineTotal(line), 120000);
});

test('discountAmount calculates discount correctly', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 5,
    unitPrice: 9500,
    vatRate: 21,
    discountPercent: 10,
  };
  assert.equal(discountAmount(line), 4750);
});

test('discountAmount with no discount returns 0', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 5,
    unitPrice: 9500,
    vatRate: 21,
  };
  assert.equal(discountAmount(line), 0);
});

test('discountAmount rounds to nearest cent', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 5,
    unitPrice: 100,
    vatRate: 21,
    discountPercent: 33.33,
  };
  assert.equal(discountAmount(line), 167);
});

test('lineVAT calculates VAT on line after discount', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 5,
    unitPrice: 9500,
    vatRate: 21,
    discountPercent: 10,
  };
  assert.equal(lineVAT(line), 8978);
});

test('lineVAT with no discount', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 5,
    unitPrice: 9500,
    vatRate: 21,
  };
  assert.equal(lineVAT(line), 9975);
});

test('lineVAT with 0% VAT rate', () => {
  const line = {
    sku: 'WORKSHOP-DAY',
